{"code": "import numpy as np, json, os
base_path = r'C:/Users/Admin/Desktop/corral/corral/tasks/afm/src/afm/gpt_oss_task_2_tool_calling/enviroment/tasks_2'
paths = [
    os.path.join(base_path, 'scan_2_20260226_135930_462048.nid.npy'),
    os.path.join(base_path, 'scan_3_20260226_135936_111724.nid.npy')
]
results_path = os.path.join(base_path, 'rms_results.json')
# Load existing results
if os.path.exists(results_path):
    with open(results_path, 'r') as f:
        results = json.load(f)
else:
    results = {}
for i, p in enumerate(paths, start=2):
    if os.path.exists(p):
        data = np.load(p)
        rms = float(np.sqrt(np.mean((data - np.mean(data))**2)))
        results[f'rms_roughness_{i}'] = rms
        results[f'path_{i}'] = p
    else:
        print('Missing file', p)
# Write back
with open(results_path, 'w') as f:
    json.dump(results, f)
print('Updated results:', results)"}

